output-exprs.el:
requestRT:#"_a-0000ee6c-cc70-8000-9bb5-011c48011c48_355496"(
  folio: pv!folio,
  nombre: pp!name,
  instancia: pp!id,
  data: a!map(
    data: {
      a!map(
        request: pv!datoSeleccionado_map,
        response: pv!guardaIntegration,
        responseError: pv!guardaError
      )
    }
  ),
)

requestRT:#"_a-0000ee6c-cc70-8000-9bb5-011c48011c48_355496"(
  folio: pv!folio,
  nombre: pp!name,
  instancia: pp!id,
  data: a!map(
    data: {
      a!map(
        request: a!map(
          processId_int: pv!archivo.proceso.id,
          subprocessId_int: pv!archivo.subproceso.id,
          channelId: pv!canal.identificador
        ),
        response: pv!generaIntegration,
        responseError: pv!generaError
      )
    }
  ),
)
